// Calcula las tags binarias necesarias para acreditar el delta del usuario.
//
// Denominaciones: [10, 20, 40, 80] — potencias de 2 × 10.
// Subsets sin repetición cubren cualquier múltiplo de 10 entre 10 y 150.
//
// Cada tag aplicada al miembro dispara una automatización en Circle que:
//   1. Suma X puntos al miembro
//   2. Remueve la tag (para que pueda re-aplicarse la próxima semana)
//
// Algoritmo greedy: de mayor a menor, agrega la denominación si cabe.
// Ejemplos:
//   delta=15  → tags:['pts-10']                              credited=10  (carry 5)
//   delta=30  → tags:['pts-20','pts-10']                     credited=30
//   delta=75  → tags:['pts-40','pts-20','pts-10']            credited=70  (carry 5)
//   delta=150 → tags:['pts-80','pts-40','pts-20','pts-10']   credited=150
//   delta=545 → tags:['pts-80','pts-40','pts-20','pts-10']   credited=150 (carry 395 → varias semanas)

const user = $input.item.json;
const delta = user.delta_points;
const denominations = [80, 40, 20, 10];

const tagsToApply = [];
let credited = 0;
let remaining = delta;

for (const value of denominations) {
  if (value <= remaining) {
    tagsToApply.push(`pts-${value}`);
    credited += value;
    remaining -= value;
  }
}

// Emite UN SOLO ITEM con el array completo de tags.
// El siguiente nodo hace UNA llamada API con todas las tags al miembro.
return [{
  json: {
    run_id: user.run_id,
    user_id: user.user_id,
    email: user.email,
    circle_member_id: user.circle_member_id,
    total_points: user.total_points,
    delta_points: delta,
    circle_last_synced_pts: user.circle_last_synced_pts,
    tags_to_apply: tagsToApply,
    credited,
    new_circle_last_synced_pts: user.circle_last_synced_pts + credited
  }
}];

